-- MySQL 8 schema for the shared web and desktop applications.
-- PostgreSQL notes: replace AUTO_INCREMENT with GENERATED BY DEFAULT AS IDENTITY;
-- replace ENUM columns with VARCHAR plus CHECK constraints; use ON CONFLICT rather
-- than INSERT IGNORE if you add repeatable seed inserts. DECIMAL, DATE, foreign keys,
-- transactions, prepared statements, and SELECT ... FOR UPDATE work in both databases.

CREATE DATABASE IF NOT EXISTS online_pharmacy
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_0900_ai_ci;
USE online_pharmacy;

CREATE TABLE IF NOT EXISTS users (
    user_id BIGINT PRIMARY KEY AUTO_INCREMENT,
    full_name VARCHAR(120) NOT NULL,
    email VARCHAR(190) NOT NULL UNIQUE,
    password_hash VARCHAR(100) NOT NULL,
    password_salt VARCHAR(100) NOT NULL,
    role ENUM('CUSTOMER', 'PHARMACIST', 'ADMIN') NOT NULL,
    address VARCHAR(500),
    license_number VARCHAR(80),
    department VARCHAR(100),
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS categories (
    category_id BIGINT PRIMARY KEY AUTO_INCREMENT,
    name VARCHAR(100) NOT NULL UNIQUE,
    parent_category_id BIGINT NULL,
    CONSTRAINT fk_category_parent
        FOREIGN KEY (parent_category_id) REFERENCES categories(category_id)
        ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS suppliers (
    supplier_id BIGINT PRIMARY KEY AUTO_INCREMENT,
    name VARCHAR(150) NOT NULL,
    contact_name VARCHAR(120),
    phone VARCHAR(40),
    email VARCHAR(190),
    address VARCHAR(500),
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS medicines (
    medicine_id BIGINT PRIMARY KEY AUTO_INCREMENT,
    name VARCHAR(180) NOT NULL,
    description TEXT,
    category_id BIGINT NOT NULL,
    supplier_id BIGINT NULL,
    unit_price DECIMAL(10, 2) NOT NULL,
    stock INT NOT NULL DEFAULT 0,
    expiry_date DATE NOT NULL,
    requires_prescription BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
        ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT chk_medicine_price CHECK (unit_price >= 0),
    CONSTRAINT chk_medicine_stock CHECK (stock >= 0),
    CONSTRAINT fk_medicine_category FOREIGN KEY (category_id)
        REFERENCES categories(category_id),
    CONSTRAINT fk_medicine_supplier FOREIGN KEY (supplier_id)
        REFERENCES suppliers(supplier_id) ON DELETE SET NULL,
    INDEX idx_medicine_name (name),
    INDEX idx_medicine_expiry (expiry_date)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS orders (
    order_id BIGINT PRIMARY KEY AUTO_INCREMENT,
    customer_id BIGINT NOT NULL,
    status ENUM('PLACED', 'PROCESSING', 'READY', 'COMPLETED', 'CANCELLED')
        NOT NULL DEFAULT 'PLACED',
    subtotal DECIMAL(10, 2) NOT NULL,
    discount_amount DECIMAL(10, 2) NOT NULL DEFAULT 0.00,
    gst_amount DECIMAL(10, 2) NOT NULL DEFAULT 0.00,
    total_amount DECIMAL(10, 2) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_order_amounts CHECK (
        subtotal >= 0 AND discount_amount >= 0 AND gst_amount >= 0 AND total_amount >= 0
    ),
    CONSTRAINT fk_order_customer FOREIGN KEY (customer_id)
        REFERENCES users(user_id),
    INDEX idx_orders_customer_date (customer_id, created_at)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS prescriptions (
    prescription_id BIGINT PRIMARY KEY AUTO_INCREMENT,
    customer_id BIGINT NOT NULL,
    medicine_id BIGINT NOT NULL,
    order_id BIGINT NULL,
    file_path VARCHAR(500) NOT NULL,
    status ENUM('PENDING', 'APPROVED', 'REJECTED') NOT NULL DEFAULT 'PENDING',
    uploaded_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    reviewed_at TIMESTAMP NULL,
    CONSTRAINT fk_prescription_customer FOREIGN KEY (customer_id)
        REFERENCES users(user_id),
    CONSTRAINT fk_prescription_medicine FOREIGN KEY (medicine_id)
        REFERENCES medicines(medicine_id),
    CONSTRAINT fk_prescription_order FOREIGN KEY (order_id)
        REFERENCES orders(order_id) ON DELETE SET NULL,
    INDEX idx_prescription_owner_medicine (customer_id, medicine_id, status)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS order_items (
    order_item_id BIGINT PRIMARY KEY AUTO_INCREMENT,
    order_id BIGINT NOT NULL,
    medicine_id BIGINT NOT NULL,
    quantity INT NOT NULL,
    unit_price DECIMAL(10, 2) NOT NULL,
    prescription_id BIGINT NULL,
    CONSTRAINT chk_order_item_quantity CHECK (quantity > 0),
    CONSTRAINT chk_order_item_price CHECK (unit_price >= 0),
    CONSTRAINT fk_item_order FOREIGN KEY (order_id)
        REFERENCES orders(order_id) ON DELETE CASCADE,
    CONSTRAINT fk_item_medicine FOREIGN KEY (medicine_id)
        REFERENCES medicines(medicine_id),
    CONSTRAINT fk_item_prescription FOREIGN KEY (prescription_id)
        REFERENCES prescriptions(prescription_id),
    INDEX idx_order_items_order (order_id)
) ENGINE=InnoDB;

