       seed.unit_price, seed.stock, seed.expiry_date, seed.requires_prescription
FROM (
    SELECT 1 medicine_id, 'Amoxicillin 500 mg' name, 'Capsule; prescription required' description,
        3 category_id, 1 supplier_id, 12.50 unit_price, 120 stock, '2028-03-31' expiry_date, TRUE requires_prescription
