    UNION ALL SELECT 3, 'Flucloxacillin 500 mg', 'Capsule; prescription required', 3, 2, 15.75, 65, '2028-05-31', TRUE
    UNION ALL SELECT 4, 'Azithromycin 250 mg', 'Tablet; prescription required', 4, 2, 18.00, 90, '2028-06-30', TRUE
    UNION ALL SELECT 5, 'Clarithromycin 500 mg', 'Tablet; prescription required', 4, 3, 22.00, 55, '2028-07-31', TRUE
    UNION ALL SELECT 6, 'Paracetamol 500 mg', 'Over-the-counter tablet', 6, 1, 2.50, 300, '2028-01-31', FALSE
    UNION ALL SELECT 7, 'Ibuprofen 200 mg', 'Over-the-counter tablet', 6, 2, 4.00, 220, '2028-02-28', FALSE
    UNION ALL SELECT 8, 'Naproxen 250 mg', 'Tablet; prescription required', 6, 3, 9.50, 70, '2028-03-31', TRUE
    UNION ALL SELECT 9, 'Cetirizine 10 mg', 'Antihistamine tablet', 7, 1, 3.50, 180, '2028-04-30', FALSE
    UNION ALL SELECT 10, 'Loratadine 10 mg', 'Antihistamine tablet', 7, 2, 4.50, 160, '2028-05-31', FALSE
    UNION ALL SELECT 11, 'Oral Rehydration Salts', 'Oral rehydration sachet', 9, 3, 1.75, 250, '2028-06-30', FALSE
    UNION ALL SELECT 12, 'Vitamin C 500 mg', 'Supplement tablet', 8, 1, 5.00, 200, '2028-07-31', FALSE
    UNION ALL SELECT 13, 'Vitamin D3 1000 IU', 'Supplement tablet', 8, 2, 6.50, 130, '2028-08-31', FALSE
    UNION ALL SELECT 14, 'Calcium 500 mg', 'Supplement tablet', 8, 3, 7.00, 110, '2028-09-30', FALSE
    UNION ALL SELECT 15, 'Omeprazole 20 mg', 'Capsule; prescription required', 9, 1, 8.50, 95, '2028-10-31', TRUE
    UNION ALL SELECT 16, 'Antacid Chewable Tablets', 'Over-the-counter antacid', 9, 2, 3.00, 140, '2028-11-30', FALSE
    UNION ALL SELECT 17, 'Cough Lozenges', 'Soothing throat lozenge', 7, 3, 2.00, 175, '2028-12-31', FALSE
    UNION ALL SELECT 18, 'Saline Nasal Spray', 'Nasal saline spray', 7, 1, 6.00, 75, '2029-01-31', FALSE
    UNION ALL SELECT 19, 'Antiseptic Solution', 'First-aid antiseptic solution', 10, 2, 9.00, 60, '2029-02-28', FALSE
    UNION ALL SELECT 20, 'Adhesive Bandages', 'Assorted first-aid bandages', 10, 3, 4.00, 240, '2029-03-31', FALSE
    UNION ALL SELECT 21, 'Cough Syrup 100 ml', 'Over-the-counter cough syrup', 7, 1, 11.00, 45, '2029-04-30', FALSE
    UNION ALL SELECT 22, 'Metformin 500 mg', 'Tablet; prescription required', 9, 2, 5.50, 100, '2029-05-31', TRUE
    UNION ALL SELECT 23, 'Lisinopril 10 mg', 'Tablet; prescription required', 1, 3, 8.00, 50, '2029-06-30', TRUE
    UNION ALL SELECT 24, 'Aspirin 75 mg', 'Low-dose tablet; prescription required', 6, 1, 3.25, 115, '2029-07-31', TRUE
) AS seed
WHERE NOT EXISTS (
    SELECT 1 FROM medicines existing WHERE existing.medicine_id = seed.medicine_id
);
